-- Japan pilot data load: Kyoto + Tokyo (Task 22)
-- Source: docs/research/japan_pilot/results_2026-10-19/ (Fable research, verified 2026-10-19).
-- Generated from places.csv / events.csv; run AFTER migrations 0011 and 0012.
-- Data upserts only. No DROP, no DELETE. Four below-threshold sources are set to 'dormant'
-- (hidden from the app, row kept), per VERIFICATION_LOG.md.
-- Mapping: Fable 'notes' (written for the reader) -> sources.about; 'underground_reason' -> sources.notes
-- (internal); places with an existing_source_id update that SRC row instead of creating a duplicate;
-- status left blank by the researcher (status unknown) -> 'active' + needs_verification = true.
BEGIN;

-- 1) 39 places -> sources
ON CONFLICT (source_id) DO UPDATE SET name = EXCLUDED.name, source_type = EXCLUDED.source_type, market = EXCLUDED.market, discipline_focus = EXCLUDED.discipline_focus, tier = EXCLUDED.tier, website_url = EXCLUDED.website_url, instagram_url = EXCLUDED.instagram_url, scrape_method = EXCLUDED.scrape_method, status = EXCLUDED.status, needs_verification = EXCLUDED.needs_verification, notes = EXCLUDED.notes, name_ja = EXCLUDED.name_ja, about = EXCLUDED.about, neighborhood = EXCLUDED.neighborhood, address = EXCLUDED.address, calendar_url = EXCLUDED.calendar_url, scene_tags = EXCLUDED.scene_tags, underground_score = EXCLUDED.underground_score, newcomer_friendly = EXCLUDED.newcomer_friendly, foreigner_notes = EXCLUDED.foreigner_notes, evidence_url = EXCLUDED.evidence_url, verified_at = EXCLUDED.verified_at, is_demo = EXCLUDED.is_demo;

-- 2) Existing rows below the underground threshold: hidden, not deleted.
UPDATE public.sources SET status = 'dormant', notes = COALESCE(notes, '') || ' | 2026-10-19: below underground threshold (Japan pilot research), retired from directory.'
  WHERE source_id IN ('SRC078', 'SRC080', 'SRC081', 'SRC261');

-- 3) 110 events
ON CONFLICT (event_id) DO UPDATE SET market = EXCLUDED.market, source_id = EXCLUDED.source_id, venue_name = EXCLUDED.venue_name, title = EXCLUDED.title, title_ja = EXCLUDED.title_ja, event_type = EXCLUDED.event_type, disciplines = EXCLUDED.disciplines, date = EXCLUDED.date, end_date = EXCLUDED.end_date, time = EXCLUDED.time, end_time = EXCLUDED.end_time, recurrence = EXCLUDED.recurrence, price_min = EXCLUDED.price_min, price_max = EXCLUDED.price_max, currency = EXCLUDED.currency, ticket_url = EXCLUDED.ticket_url, evidence_url = EXCLUDED.evidence_url, lineup = EXCLUDED.lineup, description = EXCLUDED.description, language_barrier = EXCLUDED.language_barrier, booking_required = EXCLUDED.booking_required, verified_at = EXCLUDED.verified_at, is_demo = EXCLUDED.is_demo;

COMMIT;

-- Check after running (expect 39 Kyoto/Tokyo sources incl. 2 closed, 110 events):
-- SELECT market, status, count(*) FROM public.sources WHERE market IN ('kyoto','tokyo') GROUP BY 1,2 ORDER BY 1,2;
-- SELECT market, count(*) FROM public.events WHERE market IN ('kyoto','tokyo') GROUP BY 1;
