INSERT INTO public.sources (source_id, name, source_type, market, discipline_focus, tier, website_url, instagram_url, scrape_method, status, needs_verification, notes, name_ja, about, neighborhood, address, calendar_url, scene_tags, underground_score, newcomer_friendly, foreigner_notes, evidence_url, verified_at, is_demo) VALUES
  ('SRC072', 'Kyoto Experiment', 'festival', 'kyoto', ARRAY['dance','theatre','performance','music','visual_art']::TEXT[], 1, 'https://kyoto-ex.jp/en/', 'https://www.instagram.com/kyotoexperiment/', 'html_calendar', 'active', false, 'Independent festival committee with a radical cross-genre programme; uses institutional venues but the fringe (More Experiments) is artist-run', 'KYOTO EXPERIMENT 京都国際舞台芸術祭', '2026 edition 3-25 Oct, so the first week is the last week. Post-show talks and the Share Cafe are the easiest way to meet the Kansai performing-arts crowd.', 'Citywide (KAC, ROHM, Shunjuza, E9)', NULL, 'https://kyoto-ex.jp/en/program/', ARRAY['experimental','international','festival','fringe']::TEXT[], 4, 'yes', 'Full English site; most shows subtitled or non-verbal; Festival Share Cafe after marked shows is a meeting point', 'https://kyoto-ex.jp/en/program/', '2026-10-19', false),
  ('kyo-urbanguild', 'UrBANGUILD', 'live_house', 'kyoto', ARRAY['music','dance','performance','theatre']::TEXT[], 1, 'https://urbanguild.net/', 'https://www.instagram.com/urbanguild', 'html_calendar', 'active', false, 'Artist-run 120-cap room since 2006; monthly FOuR DANCERS dance night, Butoh Night, free-improv and experimental touring acts; no-charge bar after shows', 'アバンギルド', 'The single most important Kyoto room for this client: dance nights (FOuR DANCERS has a reduced ''dancer'' ticket), butoh, improv, ambient tours. Reserve via the site form; pay cash at door.', 'Kiyamachi / Sanjo', 'New Kyoto Bldg 3F, Kiyamachi Sanjo-sagaru, Nakagyo-ku, Kyoto', 'http://urbanguild.net/events/', ARRAY['butoh','improv','experimental','ambient','noise','contact_improv','candlelit']::TEXT[], 5, 'yes', 'Listings in Japanese but lineups readable; +700 yen drink charge; bar stays open no-charge until 24:00 after events (best hang-out in Kyoto)', 'http://urbanguild.net/events/', '2026-10-19', false),
  ('kyo-kac', 'Kyoto Art Center', 'art_centre', 'kyoto', ARRAY['dance','theatre','visual_art','music']::TEXT[], 1, 'https://www.kac.or.jp/', 'https://www.instagram.com/kyotoartcenter/', 'html_calendar', 'active', false, 'City-run former school; free studios for young companies (Monochrome Circus, ANTIBODIES Collective etc.), free Meirin workshops, KEX main venue', '京都芸術センター', 'Walk in any day: the studio-user list on the site is a who''s-who of Kyoto dance. Meirin workshops are free and taught by resident artists; open calls (Co-program, KIPPU U35, studio residency) posted here.', 'Muromachi / Shijo', '546-2 Yamabushiyama-cho, Muromachi-dori Takoyakushi-sagaru, Nakagyo-ku, Kyoto', 'https://www.kac.or.jp/events/', ARRAY['artist_studios','free_workshops','residency','festival_hub']::TEXT[], 3, 'yes', 'English site; free entry to building, library, cafe (11-18); workshops booked via teket form in Japanese', 'https://www.kac.or.jp/', '2026-10-19', false),
  ('kyo-butohfes', 'Kyoto International Butoh Festival', 'festival', 'kyoto', ARRAY['dance','music']::TEXT[], 1, 'https://kyoto-butohfes.com/', NULL, 'peatix', 'active', false, 'Artist-run (Katsura Kan & committee), 60+ dancers from 47 regions over 9 nights with live musicians; the kind of room where you meet every butoh person in Japan', '京都国際舞踏祭', '4th edition 7-15 Nov 2026. Pre-event 26 Oct at UrBANGUILD with open stage (''surprise guest appearances by festival dancers'') is the networking night before the festival.', 'Higashiyama (SPACE LFAN)', 'SPACE LFAN, 10-151-1 Honmachi, Higashiyama-ku, Kyoto', 'https://kyoto-butohfes.com/', ARRAY['butoh','international','improv','festival']::TEXT[], 5, 'yes', 'Bilingual statement; many foreign dancers perform; contact kyotobutohfes@gmail.com (public festival address)', 'https://kyoto-artbox.jp/event/95892', '2026-10-19', false),
  ('kyo-spacelfan', 'SPACE LFAN', 'community_space', 'kyoto', ARRAY['dance','performance']::TEXT[], 3, NULL, NULL, 'manual', 'active', false, 'Small private space hosting the 9-night butoh festival; little public info beyond that', NULL, 'Only verified as the 2026 butoh festival venue. Near THEATRE E9 and @KCUA.', 'Higashiyama / Honmachi', '10-151-1 Honmachi, Higashiyama-ku, Kyoto', NULL, ARRAY['butoh','venue']::TEXT[], 4, 'unknown', NULL, 'https://kyoto-artbox.jp/event/95892', '2026-10-19', false),
  ('kyo-monochromecircus', 'Monochrome Circus', 'collective', 'kyoto', ARRAY['dance']::TEXT[], 1, 'https://monochromecircus.com/', NULL, 'manual', 'active', false, 'Kyoto''s contact-improvisation company (since 1990); runs CI workshops and jams at KAC and directs the Kyoto International Dance Workshop Festival', 'モノクローム・サーカス', 'The door into Kyoto contact improv. Watch KAC''s Meirin Workshop page for their next CI jam; email the company (public address on their site) to ask about open classes.', NULL, NULL, 'https://monochromecircus.com/news/', ARRAY['contact_improv','improv','company','workshops']::TEXT[], 5, 'yes', 'CI workshops are physical, not verbal; past KAC listings were Japanese-only but open to anyone', 'https://www.kac.or.jp/events/20260509/', '2026-10-19', false),
  ('kyo-kiraza', 'Butoh company Kiraza (Ima Tenko)', 'collective', 'kyoto', ARRAY['dance','music']::TEXT[], 2, 'https://imakiraza.wixsite.com/kirabutoh', NULL, 'manual', 'active', false, 'Independent butoh company led by Ima Tenko; performs in small rooms (UrBANGUILD), KEX fringe participant', '舞踏カンパニー倚羅座 / 今貂子', 'Ima Tenko performs MIZUMONO on 20 Oct and CIBELES on 30 Oct at UrBANGUILD. Ask at the bar after the show about workshops.', NULL, NULL, NULL, ARRAY['butoh','company']::TEXT[], 5, 'yes', 'Site has English notes; performances non-verbal', 'https://imakiraza.wixsite.com/kirabutoh', '2026-10-19', false),
  ('kyo-clubmetro', 'CLUB METRO', 'club', 'kyoto', ARRAY['music']::TEXT[], 1, NULL, NULL, 'manual', 'active', false, 'Long-running basement club under a station with collective-run nights (ACTIVISM!!!, Sound Maneuvers x EXP, Deep Underground techno) alongside bands', 'クラブメトロ', 'Boro Festa''s night session (31 Oct) with 食品まつり a.k.a foodman is the most experimental club night found in the window. Website not opened in this pass; use the e+ and kyoto.travel listings.', 'Jingu-Marutamachi (Keihan)', '82 Shimotsutsumi-cho, Kawabata Marutamachi, Sakyo-ku, Kyoto', NULL, ARRAY['club','electronic','experimental','collectives','techno']::TEXT[], 4, 'yes', 'Cash at door; ID may be checked at night', 'https://eplus.jp/borofesta', '2026-10-19', false),
  ('kyo-borofesta', 'Boro Festa', 'festival', 'kyoto', ARRAY['music']::TEXT[], 2, NULL, NULL, 'manual', 'active', false, 'Volunteer-run Kyoto indie festival; daytime hall stages are guitar-indie, the Metro night stage leans experimental (foodman, NATURE DANGER GANG)', 'ボロフェスタ', '31 Oct-3 Nov 2026. Go for the Metro night, skip the hall unless you like Japanese indie rock.', 'KBS Hall + Club Metro', NULL, NULL, ARRAY['indie','diy','festival','experimental_electronic']::TEXT[], 4, 'yes', 'e+ ticketing is Japanese-only; smartphone tickets', 'https://eplus.jp/borofesta', '2026-10-19', false),
  ('kyo-kcua', '@KCUA (Kyoto City University of Arts Gallery)', 'gallery', 'kyoto', ARRAY['visual_art','performance']::TEXT[], 2, 'https://gallery.kcua.ac.jp/', NULL, 'html_calendar', 'active', false, 'University gallery with an experimental programme; hosts KEX exhibitions', '京都市立芸術大学ギャラリー@KCUA', 'Kaori Endo / Mithu Sen exhibition runs to 8 Nov. The art-school crowd hangs around here and HAPS.', 'Kyoto Station east / Higashiyama', NULL, NULL, ARRAY['university_gallery','experimental']::TEXT[], 3, 'yes', 'Free; 10:00-18:00, closed Mondays', 'https://kyoto-ex.jp/en/program/', '2026-10-19', false),
  ('kyo-rohm', 'ROHM Theatre Kyoto', 'art_centre', 'kyoto', ARRAY['theatre','dance','music']::TEXT[], 2, 'https://rohmtheatrekyoto.jp/', NULL, 'html_calendar', 'active', false, 'Public theatre; include only for KEX and the ''Hopes'' repertory premieres and the U35 KIPPU programme', 'ロームシアター京都', 'Institutional. Worth it for ''Hopes'' repertory (30 Oct-1 Nov, 6-8 Nov) and as KEX venue; otherwise skip.', 'Okazaki', NULL, NULL, ARRAY['institution','repertory','kex_venue']::TEXT[], 3, 'yes', 'English site', 'https://kyoto-ex.jp/en/program/', '2026-10-19', false),
  ('kyo-theatre-e9', 'THEATRE E9 KYOTO', 'theatre_small', 'kyoto', ARRAY['theatre','dance']::TEXT[], 2, 'https://askyoto.or.jp/e9', NULL, 'html_calendar', 'active', false, 'Crowdfunded independent black box opened 2019; KEX venue; hosts Monochrome Circus and young companies', 'シアターE9京都', 'Listed as a 2026 KEX venue. Programme page not opened in this pass; check askyoto.or.jp/e9 weekly.', 'Higashi-Kujo (south of Kyoto Station)', '9-1 Higashikujo Minamikawara-cho, Minami-ku, Kyoto', NULL, ARRAY['black_box','independent_theatre','kex_venue']::TEXT[], 4, 'yes', 'Office hours 10-18, closed Tue', 'https://kyoto-ex.jp/en/about/festival-overview/', '2026-10-19', false),
  ('kyo-haps', 'HAPS (Higashiyama Artists Placement Service)', 'community_space', 'kyoto', ARRAY['visual_art','performance']::TEXT[], 1, 'https://haps-kyoto.com/', 'https://www.instagram.com/hapskyoto/', 'html_calendar', 'active', false, 'Artist-support office run by artists for artists: free consultation desk, studio/space listings, open-call digest, and ''Enjoy Exhibition Club'' group gallery walks', '東山 アーティスツ・プレイスメント・サービス', 'Best first stop for a foreign artist who wants to meet Kyoto people: ask for a consultation slot and join the next Enjoy Exhibition Club walk (#14 announced 16 Oct).', 'Higashiyama', NULL, 'https://haps-kyoto.com/blog', ARRAY['artist_support','consultation','open_calls','gallery_club']::TEXT[], 4, 'yes', 'English page; consultation by form', 'https://haps-kyoto.com/', '2026-10-19', false),
  ('kyo-kidwf', 'Kyoto International Dance Workshop Festival (Kyoto no Atsui Natsu)', 'festival', 'kyoto', ARRAY['dance']::TEXT[], 1, 'https://www.kac.or.jp/events/20260330/', NULL, 'html_calendar', 'active', false, '30-year-old workshop festival run by Dance & Environment / Monochrome Circus with KAC; international teachers, CI and improv strands, open enrolment', '京都国際ダンスワークショップフェスティバル「京都の暑い夏」', '2026: early-summer edition 2-6 May, main edition 1-9 Aug. Not in the window; put it in the client''s calendar for 2027.', 'Kyoto Art Center', NULL, NULL, ARRAY['workshops','contact_improv','international_teachers','intensive']::TEXT[], 4, 'yes', 'International faculty; classes taught in English/Japanese', 'https://digitalpr.jp/pdf.php?r=139061', '2026-10-19', false),
  ('kyo-dancebox', 'DANCE BOX / ArtTheater dB Kobe', 'theatre_small', 'kyoto', ARRAY['dance']::TEXT[], 1, 'https://db-dancebox.org', 'https://www.instagram.com/dancebox_kobe/', 'html_calendar', 'active', false, 'NPO-run 120-seat dance theatre in a shopping arcade; 8-month ''domestic dance study abroad'' residency, open classes, AIR, butoh seasons', 'NPO法人DANCE BOX／アートシアターdB神戸', 'Day trip - Kobe: 1h from Kyoto by train. The most dancer-dense community in Kansai; the Nov 16-18 intensive is an ''open class'' tagged event.', 'Day trip - Kobe: Shin-Nagata', 'Asta Kunizuka 4-bankan 4F, 6-1-1 Kubo-cho, Nagata-ku, Kobe', 'https://db-dancebox.org/event', ARRAY['contemporary','open_class','residency','butoh','community']::TEXT[], 5, 'yes', 'Japanese site; AIR programme hosts foreign artists so staff are used to English', 'https://db-dancebox.org', '2026-10-19', false),
  ('kyo-kyotoartbox', 'Kyoto Art Box', 'aggregator', 'kyoto', ARRAY['visual_art','dance','theatre','music']::TEXT[], 2, 'https://kyoto-artbox.jp/', NULL, 'html_calendar', 'active', false, 'City-run listing; mostly institutions but small organisers (butoh festival) post here too', '京都文化芸術オフィシャルサイト Kyoto Art Box', 'Filter by ダンス/音楽 and 公演/ワークショップ. Low signal-to-noise but structured dates.', NULL, NULL, 'https://kyoto-artbox.jp/event/', ARRAY['city_listing','searchable']::TEXT[], 3, 'yes', NULL, 'https://kyoto-artbox.jp/event/', '2026-10-19', false),
  ('kyo-kyototravel-night', 'Kyoto City Tourism ''Night events'' listing (ja.kyoto.travel)', 'aggregator', 'kyoto', ARRAY['music','performance']::TEXT[], 3, 'https://ja.kyoto.travel/times/night/event/', NULL, 'html_calendar', 'active', false, 'Tourism-board page, but it mirrors Club Metro and UrBANGUILD nights with dates', '京都観光Navi 夜観光イベント一覧', 'Useful only as a cross-check of Metro/UrBANGUILD dates.', NULL, NULL, NULL, ARRAY['city_listing','club_nights','livehouse']::TEXT[], 3, 'yes', NULL, 'https://ja.kyoto.travel/times/night/event/', '2026-10-19', false),
  ('kyo-kyotographie', 'KYOTOGRAPHIE / KYOTOPHONIE / KG+', 'festival', 'kyoto', ARRAY['photography','music','visual_art']::TEXT[], 2, NULL, NULL, 'manual', 'active', false, 'Large international photo festival; KG+ satellite programme is where emerging artists show in small spaces', NULL, 'Spring (kick-off party 18 Apr 2026 at Club Metro). Not in window; festival calendar only. Verified via listing snippet only.', NULL, NULL, NULL, ARRAY['photo_festival','spring','kg_plus_fringe']::TEXT[], 3, 'yes', NULL, 'https://ja.kyoto.travel/search-area01.php?area_id=2', '2026-10-19', false),
  ('kyo-shunjuza', 'Kyoto Art Theater Shunjuza', 'theatre_small', 'kyoto', ARRAY['theatre','dance']::TEXT[], 3, NULL, NULL, 'manual', 'active', false, 'University theatre; relevant as a KEX venue', '京都芸術劇場 春秋座', 'Only verified as a 2026 KEX venue.', 'Kitashirakawa (Kyoto University of the Arts)', NULL, NULL, ARRAY['university_theatre','kex_venue']::TEXT[], 3, 'yes', NULL, 'https://kyoto-ex.jp/en/about/festival-overview/', '2026-10-19', false),
  ('SRC070', 'Ftarri', 'venue_music', 'tokyo', ARRAY['music','sound']::TEXT[], 1, 'https://www.ftarri.com/', NULL, 'html_calendar', 'active', false, 'Label-run 20-seat basement shop/venue; nightly improvised and experimental concerts with visiting European players', 'Ftarri（水道橋）', 'Concerts 20:00 (doors 19:30), 2000-4000 yen. With 20 seats you will talk to the musicians. Best Tokyo entry point for experimental music.', 'Suidobashi / Hongo', 'Okano Bldg B1F, 1-4-11 Hongo, Bunkyo-ku, Tokyo 113-0033', 'https://www.ftarri.com/suidobashi/index-e.html', ARRAY['improv','experimental','electroacoustic','record_shop','20_seats']::TEXT[], 5, 'yes', 'English schedule; reserve by email with name, date, number; cash only; BYO drinks allowed; no smoking', 'https://www.ftarri.com/suidobashi/index-e.html', '2026-10-19', false),
  ('SRC259', 'FORESTLIMIT', 'club', 'tokyo', ARRAY['music','visual_art']::TEXT[], 1, 'https://www.forestlimit.com', 'https://www.instagram.com/forestlimit_info/', 'html_calendar', 'active', false, 'Independently run basement where collectives (Massacre series, nannou, experienc(e), Sustain) throw live/DJ nights; also hosts small exhibitions', '幡ヶ谷フォレストリミット', 'Ambient/experimental artists like yolabmi and Sofheso play here. Weeknight shows start ~18:30-19:00; weekend parties are all-nighters. Check event page for each lineup.', 'Hatagaya', NULL, 'https://www.forestlimit.com', ARRAY['experimental_electronic','ambient','noise','collectives','all_night','exhibitions']::TEXT[], 5, 'yes', 'Lineups in roman letters; 2000-3500 yen + drink; many nights run 22:00-05:00', 'https://www.forestlimit.com', '2026-10-19', false),
  ('SRC075', 'Kagurazaka Session House', 'dance_studio', 'tokyo', ARRAY['dance']::TEXT[], 1, 'https://session-house.net/', NULL, 'html_calendar', 'active', false, 'Independent dance house since 1991: weekday open classes (ballet, contemporary, somatic), weekend studio-theatre showcases (Dance Theater 21 Fes, D-Zone), Gaga workshops', '神楽坂セッションハウス', 'The place to take class in Tokyo and to see 10-minute pieces by local dancers (21 Fes). Also runs open calls (21 Fes slots open 4 Nov; Dzone 2027 deadline 31 Oct).', 'Kagurazaka', '158 Yarai-cho, Shinjuku-ku, Tokyo 162-0805', 'https://session-house.net/live_news.html', ARRAY['contemporary','open_class','gaga','somatic','showcase','small_theatre']::TEXT[], 4, 'yes', 'English site; classes booked via Airreserve calendar or phone; drop-in classes exist', 'https://session-house.net/live_news.html', '2026-10-19', false),
  ('tyo-autumnmeteorite', 'Tokyo Festival / Autumn Meteorite 2026 Tokyo', 'festival', 'tokyo', ARRAY['theatre','dance','performance']::TEXT[], 1, 'https://autumnmeteorite.jp/', 'https://www.instagram.com/geigeki_info/', 'html_calendar', 'active', false, 'Public festival directed by Toshiki Okada with a sharp international programme (Beugré, Ahe Engineering Theatre); institutional venue', '東京舞台芸術祭 舞台芸術祭「秋の隕石2026東京」', '9 Oct-3 Nov 2026. ''Next: look, talk'' residency (22 Oct-2 Nov) brings young international makers to town - good people to meet at post-show talks.', 'Ikebukuro (Tokyo Metropolitan Theatre)', NULL, 'https://www.geigeki.jp/performance/theater415/', ARRAY['international','experimental','okada_toshiki','object_theatre']::TEXT[], 3, 'yes', 'Japanese/English surtitles on most shows; U29 3000 yen tickets', 'https://www.geigeki.jp/performance/theater415/', '2026-10-19', false),
  ('tyo-geigeki', 'Tokyo Metropolitan Theatre', 'art_centre', 'tokyo', ARRAY['theatre','dance','music']::TEXT[], 2, 'https://www.geigeki.jp/', NULL, 'html_calendar', 'active', false, 'Public theatre; only relevant while it hosts Autumn Meteorite under Okada', '東京芸術劇場', 'Venue row for festival events only.', 'Ikebukuro', '1-8-1 Nishi-Ikebukuro, Toshima-ku, Tokyo', 'https://www.geigeki.jp/calendar/', ARRAY['institution','festival_venue']::TEXT[], 3, 'yes', 'English site and box office', 'https://www.geigeki.jp/performance/theater415/', '2026-10-19', false),
  ('SRC260', 'Art Center Ongoing', 'artist_run_space', 'tokyo', ARRAY['visual_art','performance','sound']::TEXT[], 1, 'https://www.ongoing.jp/', 'https://www.instagram.com/artcenter_ongoing/', 'html_calendar', 'active', false, 'Artist-run gallery with a cafe/bar and artist library; residency; talks and live events; the Kichijoji art crowd''s living room', 'アートセンター・オンゴーイング', 'Go on a Friday evening, sit at the bar. Exhibition ''Figure Children'' by Yoshinori Kawamoto runs 21 Oct-1 Nov.', 'Kichijoji', '1-8-7 Kichijoji Higashi-cho, Musashino-shi, Tokyo 180-0002', 'https://www.ongoing.jp/exhibition/', ARRAY['artist_run','bar','residency','talks']::TEXT[], 5, 'yes', 'English page; open Wed-Thu 18-21, Fri-Sun 12-21', 'https://www.ongoing.jp', '2026-10-19', false),
  ('tyo-buoy', 'BUoY Arts Center Tokyo', 'art_centre', 'tokyo', ARRAY['performance','dance','visual_art','music','theatre']::TEXT[], 1, 'https://buoy.or.jp/', 'https://www.instagram.com/buoy_tokyo/', 'html_calendar', 'active', false, 'Artist-run centre in a derelict bowling alley/bathhouse; hosts performance collectives (RAW PARTY), dance, experimental music and its own NAFAS festival', '北千住BUoY', 'East-side anchor. RAW PARTY nights include an ''independent'' open slot for anyone who wants to perform.', 'Kita-Senju', '49-11 Senju Naka-cho, Adachi-ku, Tokyo 120-0036', 'https://buoy.or.jp/#event', ARRAY['artist_run','former_bathhouse','performance_art','nafas_festival','cafe']::TEXT[], 5, 'yes', 'Japanese site; cafe on site; 6 min from Kita-Senju station', 'http://buoy.or.jp/', '2026-10-19', false),
  ('tyo-rawparty', 'RAW PARTY (牢)', 'collective', 'tokyo', ARRAY['performance','dance']::TEXT[], 2, NULL, 'https://www.instagram.com/_raw_party', 'instagram_only', 'active', false, 'Performance-art collective night at BUoY with an ''indépendants'' open section for anyone to join', '『牢／RAW PARTY』', 'vol.5 was 10 Oct 2026; next date not announced. Follow the Instagram and DM to join the open section.', 'Kita-Senju (BUoY)', NULL, NULL, ARRAY['performance_art','open_stage','collective']::TEXT[], 5, 'yes', 'Instagram only; performers include Aokid and other dance/performance names', 'https://www.tokyoartbeat.com/events/-/Raw-Party-Vol5/704-F9579/2026-10-10', '2026-10-19', false),
  ('SRC069', 'SUPER DOMMUNE', 'media', 'tokyo', ARRAY['music','sound','visual_art']::TEXT[], 2, 'https://www.dommune.com/', NULL, 'html_calendar', 'active', false, 'Ukawa Naohiro''s streaming studio; nightly DJ/live/talk programmes with limited studio audiences; curatorially extreme, physically a Parco floor', 'スーパードミューン', 'Moved to Shibuya PARCO 9F. Use it as a scanner of who is in town (touring DJs stream here before club dates) rather than as a venue.', 'Shibuya (PARCO 9F)', NULL, 'https://www.dommune.com/', ARRAY['livestream','studio','dj','talks','electronic']::TEXT[], 4, 'yes', 'Talk programmes are in Japanese; DJ nights (BROADJ) need no language', 'https://dommune.com', '2026-10-19', false),
  ('SRC071', 'Higashi-Koenji Nijuuman Denatsu (20000V)', 'live_house', 'tokyo', ARRAY['music']::TEXT[], 3, NULL, NULL, 'manual', 'active', false, 'Small DIY live house (16 years in Oct 2026) but recent bookings skew to visual-kei/idol nights; check each lineup', '東高円寺二万電圧', 'Keep in DB but demoted: programme in 2026 is mostly not experimental. Official site not opened in this pass.', 'Higashi-Koenji', 'L-GRAZIA Higashi-Koenji B1, 1-7-23 Koenji-Minami, Suginami-ku, Tokyo', NULL, ARRAY['livehouse','hardcore','noise','visual_kei_mix']::TEXT[], 3, 'yes', 'Japanese-only listings', 'https://eplus.jp/sf/venue/1660310', '2026-10-19', false),
  ('tyo-nishiogi-ci', 'Nishiogikubo Contact Improvisation WS & Jam', 'collective', 'tokyo', ARRAY['dance']::TEXT[], 1, 'https://contactimprov-nn.com/workshop-list/nishiogi/', NULL, 'manual', 'active', true, 'Volunteer-run CI class + jam twice a month; 500-1500 yen; no booking; explicit English welcome', 'コンタクトインプロビゼーションWs＆Jam 西荻窪', '1st Sat: 14:00 class, 15:30-18:00 jam; 3rd Sat: 14:00-18:00. Page is undated - confirm on Facebook before going (status left blank).', 'Nishi-Ogikubo', 'Izumida Ballet Studio, 4-2-1 Kamiogi, Suginami-ku, Tokyo', NULL, ARRAY['contact_improv','jam','open_class','english_info']::TEXT[], 5, 'yes', 'English description on page; first-timers free on 1st Saturdays; contact nishiogici@gmail.com (public) or Facebook', 'https://contactimprov-nn.com/workshop-list/nishiogi/', '2026-10-19', false),
  ('tyo-dairakudakan', 'Dairakudakan / Kochuten', 'collective', 'tokyo', ARRAY['dance']::TEXT[], 1, NULL, NULL, 'manual', 'active', false, 'Maro Akaji''s butoh company (since 1972); Kochuten studio series lets company members direct small-scale works', '大駱駝艦・壺中天', 'No Tokyo dates found inside the window (their 2026 Kobe butoh season was at Dance Box). Ask about Kochuten studio workshops.', 'Kichijoji (studio) / Za-Koenji (shows)', NULL, NULL, ARRAY['butoh','company','temputenshiki']::TEXT[], 5, 'yes', 'Non-verbal; company site not opened in this pass', 'https://natalie.mu/stage/news/671537', '2026-10-19', false),
  ('tyo-miminoimi', 'MIMINOIMI Ambient Week', 'collective', 'tokyo', ARRAY['music','sound']::TEXT[], 1, NULL, NULL, 'manual', 'active', false, 'Organiser collective (with ''TENbient'') running a yearly week of ambient/drone concerts, talks and workshops across small Tokyo rooms and DOMMUNE', 'MIMINOIMI - Ambient / Week', '2026 edition was in May (Day 5 on DOMMUNE 8 May). Directly matches the client''s ambient taste; nothing in the window, but the network (Ayami Suzuki, soma hayato, Ken Ikeda) plays Ftarri and Forestlimit all year.', NULL, NULL, NULL, ARRAY['ambient','drone','deep_listening','festival_week','talks']::TEXT[], 5, 'yes', 'Music is non-verbal; talks in Japanese', 'https://dommune.com', '2026-10-19', false),
  ('tyo-artweektokyo', 'Art Week Tokyo', 'festival', 'tokyo', ARRAY['visual_art']::TEXT[], 2, 'https://www.artweektokyo.com/', NULL, 'manual', 'active', false, 'Art Basel-backed gallery week; mainstream institutions, but 55 galleries open free and the AWT Bar is where the whole art scene drinks for five nights', NULL, '4-8 Nov 2026 (overlaps the client''s last Tokyo days). Dates verified on secondary sources only; official site not opened.', 'Citywide; AWT Bar in Minami-Aoyama', NULL, NULL, ARRAY['gallery_week','free_bus','awt_bar','institutional']::TEXT[], 3, 'yes', 'Fully English', 'https://metropolisjapan.com/events/art-week-tokyo-2026/', '2026-10-19', false),
